import Link from 'next/link';
import type { ReactNode } from 'react';
import type { AnalyzeResponse, Priority } from '@/lib/types';

const priorityRank: Record<Priority, number> = {
  high: 0,
  medium: 1,
  low: 2,
};

const priorityLabel: Record<Priority, string> = {
  high: '高优先级',
  medium: '中优先级',
  low: '低优先级',
};

const meterTone = {
  blue: 'bg-blue-500',
  amber: 'bg-amber-500',
} as const;

type ResultDashboardProps = {
  result: AnalyzeResponse;
  toolbar?: ReactNode;
};

export function ResultDashboard({ result, toolbar }: ResultDashboardProps) {
  const sortedSkillGaps = [...result.skillGaps].sort(
    (a, b) => priorityRank[a.priority] - priorityRank[b.priority],
  );
  const gapCount = result.skillGaps.filter((skill) => skill.status === 'gap').length;
  const strengthCount = result.skillGaps.length - gapCount;
  const totalHours = result.learningPlan.reduce((sum, step) => sum + step.estimatedHours, 0);

  return (
    <main className="mx-auto w-full max-w-6xl px-4 py-10 sm:py-14">
      <header className="mb-8 flex flex-col gap-4 sm:flex-row sm:items-end sm:justify-between">
        <div className="max-w-2xl">
          <p className="text-sm font-medium text-blue-700">AI 技能转型导航</p>
          <h1 className="mt-2 text-2xl font-semibold tracking-tight sm:text-3xl">转型建议报告</h1>
          <p className="mt-2 text-sm leading-6 text-slate-600">
            基于你提交的岗位、任务与学习投入生成的示例报告。所有分数与工时均为估计值。
          </p>
        </div>
        <div className="flex flex-wrap items-center gap-2">
          <span className="rounded-full bg-blue-50 px-3 py-1.5 text-xs font-medium text-blue-700">
            示例数据
          </span>
          <Link
            href="/"
            className="rounded-full border border-slate-300 bg-white px-3 py-1.5 text-xs font-medium text-slate-700 transition hover:border-slate-400 hover:text-slate-900"
          >
            重新填写
          </Link>
        </div>
      </header>

      {toolbar ? <div className="mb-5">{toolbar}</div> : null}

      <div className="space-y-5">
        <Card title="技能画像" badge={`${result.extractedSkills.length} 项`}>
          <div className="grid gap-3 sm:grid-cols-2">
            {result.extractedSkills.map((skill) => (
              <div key={skill.name} className="rounded-xl border border-slate-100 bg-slate-50/70 p-4">
                <div className="flex items-center gap-2">
                  <span className="h-1.5 w-1.5 rounded-full bg-blue-500" aria-hidden="true" />
                  <p className="text-sm font-medium text-slate-900">{skill.name}</p>
                </div>
                <p className="mt-1.5 text-xs leading-5 text-slate-500">{skill.evidence}</p>
              </div>
            ))}
          </div>
        </Card>

        <Card title="任务变化" badge={`${result.taskChanges.length} 项任务`}>
          <ul className="space-y-3">
            {result.taskChanges.map((item) => (
              <li key={item.task} className="rounded-xl border border-slate-100 p-4">
                <div className="flex flex-col gap-4 lg:flex-row lg:items-center lg:justify-between">
                  <div className="lg:max-w-sm">
                    <p className="text-sm font-medium text-slate-900">{item.task}</p>
                    <a
                      href={item.source.url}
                      target="_blank"
                      rel="noreferrer"
                      className="mt-1 inline-flex items-center gap-1 text-xs text-slate-500 underline-offset-2 transition hover:text-slate-900 hover:underline"
                    >
                      {item.source.name} · {item.source.date}
                      <span aria-hidden="true">↗</span>
                    </a>
                  </div>
                  <div className="grid w-full gap-3 sm:grid-cols-2 lg:max-w-md">
                    <Meter label="AI 影响" value={item.aiImpact} tone="blue" />
                    <Meter label="人类判断" value={item.humanJudgment} tone="amber" />
                  </div>
                </div>
              </li>
            ))}
          </ul>
        </Card>

        <Card title="相邻岗位" badge={`${result.recommendedRoles.length} 个方向`}>
          <div className="grid gap-4 md:grid-cols-3">
            {result.recommendedRoles.map((role) => (
              <article
                key={role.title}
                className="flex flex-col rounded-xl border border-slate-100 p-4 transition hover:border-slate-200 hover:shadow-sm"
              >
                <div className="flex items-start justify-between gap-2">
                  <h3 className="text-sm font-semibold leading-5 text-slate-900">{role.title}</h3>
                  <p className="shrink-0 text-right">
                    <span className="block text-2xl font-semibold tabular-nums tracking-tight text-slate-900">
                      {role.matchScore}
                    </span>
                    <span className="block text-[10px] font-medium text-slate-400">匹配分</span>
                  </p>
                </div>
                <div
                  className="mt-2 h-1.5 overflow-hidden rounded-full bg-slate-100"
                  role="progressbar"
                  aria-label={`${role.title} 匹配分`}
                  aria-valuemin={0}
                  aria-valuemax={100}
                  aria-valuenow={role.matchScore}
                >
                  <div
                    className="h-full rounded-full bg-emerald-500"
                    style={{ width: `${role.matchScore}%` }}
                  />
                </div>
                <ul className="mt-4 space-y-1.5">
                  {role.reasons.map((reason) => (
                    <li key={reason} className="flex gap-2 text-xs leading-5 text-slate-600">
                      <span
                        className="mt-2 h-1 w-1 shrink-0 rounded-full bg-slate-300"
                        aria-hidden="true"
                      />
                      <span>{reason}</span>
                    </li>
                  ))}
                </ul>
                <div className="mt-4 space-y-2.5 border-t border-slate-100 pt-3">
                  <SkillChips label="已匹配技能" items={role.matchedSkills} tone="matched" />
                  <SkillChips label="待补技能" items={role.missingSkills} tone="missing" />
                </div>
              </article>
            ))}
          </div>
          <p className="mt-4 text-xs leading-5 text-slate-400">
            匹配分 = 技能重合度 + 兴趣小幅调整，仅用于岗位排序，不代表录用概率。
          </p>
        </Card>

        <div className="grid gap-5 lg:grid-cols-2">
          <Card title="技能差距" badge={`${gapCount} 项待补`} className="h-full">
            <ul className="space-y-2.5">
              {sortedSkillGaps.map((skill) => {
                const isGap = skill.status === 'gap';
                return (
                  <li
                    key={skill.skill}
                    className={`flex items-center justify-between gap-3 rounded-xl border p-3 ${
                      isGap
                        ? 'border-rose-100 bg-rose-50/50'
                        : 'border-emerald-100 bg-emerald-50/50'
                    }`}
                  >
                    <div className="flex min-w-0 items-center gap-3">
                      <span
                        className={`flex h-8 w-8 shrink-0 items-center justify-center rounded-lg text-xs font-semibold ${
                          isGap ? 'bg-rose-100 text-rose-700' : 'bg-emerald-100 text-emerald-700'
                        }`}
                        aria-hidden="true"
                      >
                        {isGap ? '补' : '优'}
                      </span>
                      <div className="min-w-0">
                        <p className="truncate text-sm font-medium text-slate-900">{skill.skill}</p>
                        <p className={`text-xs ${isGap ? 'text-rose-600' : 'text-emerald-600'}`}>
                          {isGap ? '待补差距' : '现有优势'}
                        </p>
                      </div>
                    </div>
                    <span className="shrink-0 rounded-full border border-slate-200 bg-white px-2.5 py-1 text-[11px] font-medium text-slate-600">
                      {priorityLabel[skill.priority]}
                    </span>
                  </li>
                );
              })}
            </ul>
            <p className="mt-3 text-xs text-slate-400">
              按优先级从高到低排列 · 现有优势 {strengthCount} 项
            </p>
          </Card>

          <Card title="学习计划" badge={`合计 ${totalHours} 小时`} className="h-full">
            <ol>
              {result.learningPlan.map((step, index) => (
                <li
                  key={`${step.step}-${index}`}
                  className="flex gap-3 border-b border-slate-100 py-3 first:pt-0 last:border-0 last:pb-0"
                >
                  <span className="flex h-7 w-7 shrink-0 items-center justify-center rounded-full bg-slate-900 text-xs font-semibold text-white">
                    {index + 1}
                  </span>
                  <div className="min-w-0 flex-1">
                    <p className="text-sm font-medium leading-5 text-slate-900">{step.step}</p>
                    <div className="mt-1 flex flex-wrap items-center gap-x-3 gap-y-1 text-xs text-slate-500">
                      <span>补足 {step.skillGap}</span>
                      <span className="text-slate-300" aria-hidden="true">
                        ·
                      </span>
                      <span>{step.estimatedHours} 小时</span>
                    </div>
                    <a
                      href={step.resource.url}
                      target="_blank"
                      rel="noreferrer"
                      className="mt-1 inline-flex items-center gap-1 text-xs font-medium text-blue-700 underline-offset-2 transition hover:text-blue-800 hover:underline"
                    >
                      {step.resource.name}
                      <span aria-hidden="true">↗</span>
                    </a>
                  </div>
                </li>
              ))}
            </ol>
          </Card>
        </div>

        <div className="grid gap-5 lg:grid-cols-2">
          <Card title="SDG 关联" badge={`${result.sdgLinks.length} 项目标`} className="h-full">
            <ul className="space-y-3">
              {result.sdgLinks.map((link) => (
                <li key={link.goal} className="rounded-xl border border-slate-100 p-4">
                  <span className="inline-flex rounded-md bg-blue-50 px-2 py-1 text-xs font-medium text-blue-700">
                    {link.goal}
                  </span>
                  <p className="mt-2 text-sm leading-6 text-slate-600">{link.reason}</p>
                </li>
              ))}
            </ul>
          </Card>

          <Card title="情景说明" badge="估计性质" className="h-full">
            <div className="rounded-xl border border-blue-100 bg-blue-50/60 p-4">
              <p className="text-sm leading-6 text-slate-700">{result.scenarioNote}</p>
            </div>
          </Card>
        </div>
      </div>
    </main>
  );
}

function Card({
  title,
  badge,
  children,
  className = '',
}: {
  title: string;
  badge?: ReactNode;
  children: ReactNode;
  className?: string;
}) {
  return (
    <section
      className={`rounded-2xl border border-slate-200 bg-white p-5 shadow-sm sm:p-6 ${className}`}
    >
      <div className="mb-4 flex items-center justify-between gap-3">
        <h2 className="text-base font-semibold tracking-tight text-slate-900">{title}</h2>
        {badge ? (
          <span className="shrink-0 rounded-full bg-slate-100 px-2.5 py-1 text-xs font-medium text-slate-600">
            {badge}
          </span>
        ) : null}
      </div>
      {children}
    </section>
  );
}

function Meter({
  label,
  value,
  tone,
}: {
  label: string;
  value: number;
  tone: keyof typeof meterTone;
}) {
  const safeValue = Math.min(100, Math.max(0, value));

  return (
    <div>
      <div className="flex items-baseline justify-between gap-2">
        <span className="text-xs text-slate-500">{label}</span>
        <span className="text-sm font-semibold tabular-nums text-slate-900">{safeValue}%</span>
      </div>
      <div
        className="mt-1.5 h-1.5 overflow-hidden rounded-full bg-slate-100"
        role="progressbar"
        aria-label={label}
        aria-valuemin={0}
        aria-valuemax={100}
        aria-valuenow={safeValue}
      >
        <div
          className={`h-full rounded-full ${meterTone[tone]}`}
          style={{ width: `${safeValue}%` }}
        />
      </div>
    </div>
  );
}

function SkillChips({
  label,
  items,
  tone,
}: {
  label: string;
  items: string[];
  tone: 'matched' | 'missing';
}) {
  const chipClass =
    tone === 'matched' ? 'bg-emerald-50 text-emerald-700' : 'bg-rose-50 text-rose-700';

  return (
    <div>
      <p className="text-[11px] font-medium text-slate-400">{label}</p>
      <div className="mt-1 flex flex-wrap gap-1.5">
        {items.length > 0 ? (
          items.map((item) => (
            <span
              key={item}
              className={`rounded-md px-2 py-0.5 text-[11px] font-medium ${chipClass}`}
            >
              {item}
            </span>
          ))
        ) : (
          <span className="text-[11px] text-slate-400">暂无</span>
        )}
      </div>
    </div>
  );
}
